   51 | pub struct UpdateMap {
   52 |     pub update_entries: Vec<UpdateMapEntry>,
   53 |     /// If true, the map will be replaced entirely with the new entries.
   54 |     /// If false, the new entries will be merged with the existing map.
   55 |     pub replace: bool,
